<?php
session_start();if(empty($_SESSION['user_id'])){header('Location: login.html');exit;}
require __DIR__.'/db.php';require __DIR__.'/event-common.php';$uid=(int)$_SESSION['user_id'];if(!eventStudent($conn,$uid)){header('Location: admin/events.php');exit;}
$s=$conn->prepare('SELECT e.event_id,e.title,e.venue,e.starts_at,r.status,r.registered_at FROM event_registrations r JOIN events e ON e.event_id=r.event_id WHERE r.user_id=? ORDER BY e.starts_at DESC');$s->bind_param('i',$uid);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Exhibitions | MIRA</title><script>try{document.documentElement.dataset.theme=localStorage.getItem('mira-theme')||'light'}catch(e){}</script><link rel="stylesheet" href="event.css"><script src="theme.js" defer></script></head><body class="event-page"><main class="event-container"><header class="event-top"><a href="user-home.php">← MIRA Home</a><a href="exhibitions.php">Browse Exhibitions</a><button type="button" class="theme-toggle">🌙</button></header><h1>My exhibitions ✦</h1><p class="event-muted">Track your registrations and attendance.</p><div class="event-public-grid"><?php foreach($rows as $r):?><article class="event-card"><h2><?=eventEsc($r['title'])?></h2><p><?=eventEsc($r['venue'])?></p><p class="event-muted"><?=eventEsc(date('M j, Y g:i A',strtotime($r['starts_at'])))?></p><span class="event-status"><?=eventEsc(ucfirst($r['status']))?></span></article><?php endforeach;?><?php if(!$rows):?><div class="event-card">You have not registered for any exhibitions yet.</div><?php endif;?></div></main></body></html>
